public class DeviceHistoryDto{private Long deviceId;private String deviceName,ipAddress;private int sampleCount;private double availabilityPercent,averageLatencyMs;private List<MetricResponseDto> metrics;private LocalDateTime generatedAt;public Long getDeviceId(){return deviceId;}public void setDeviceId(Long v){deviceId=v;}public String getDeviceName(){return deviceName;}public void setDeviceName(String v){deviceName=v;}public String getIpAddress(){return ipAddress;}public void setIpAddress(String v){ipAddress=v;}public int getSampleCount(){return sampleCount;}public void setSampleCount(int v){sampleCount=v;}public double getAvailabilityPercent(){return availabilityPercent;}public void setAvailabilityPercent(double v){availabilityPercent=v;}public double getAverageLatencyMs(){return averageLatencyMs;}public void setAverageLatencyMs(double v){averageLatencyMs=v;}public List<MetricResponseDto> getMetrics(){return metrics;}public void setMetrics(List<MetricResponseDto> v){metrics=v;}public LocalDateTime getGeneratedAt(){return generatedAt;}public void setGeneratedAt(LocalDateTime v){generatedAt=v;}}
